if(!'package:creditratingsystem'%in%search())library(creditratingsystem)
resource<-function(inst,local){p<-system.file(inst,package='creditratingsystem');if(nzchar(p))p else local}
source(resource('examples/revolving_lifecycle.R','creditratingsystem-r/examples/revolving_lifecycle.R'))
d<-jsonlite::fromJSON(resource('extdata/revolving_lifecycle.json','creditratingsystem-r/inst/extdata/revolving_lifecycle.json'),simplifyVector=FALSE)
args<-list(data=d,accounts_path=resource('extdata/revolving_accounts.csv','creditratingsystem-r/inst/extdata/revolving_accounts.csv'),releases_path=resource('extdata/revolving_releases.csv','creditratingsystem-r/inst/extdata/revolving_releases.csv'),input_helper_path=resource('examples/input_lineage.R','creditratingsystem-r/examples/input_lineage.R'),return_artifacts=TRUE)
card<-'RETAIL_CREDIT_CARD';r<-do.call(run_revolving_lifecycle,c(args,list(product_ids=card)));q<-r$products[[card]];raw<-r$raw_artifacts$products[[card]]
stopifnot(all(unlist(q$application_pd)==.03),all(unlist(q$decision_actions)=='APPROVE'),identical(lapply(q$application_targets,function(x)x$target),list(0,1,NULL)),abs(unlist(q$ead_forecast)-750)<1e-9,abs(q$observed_ccf$ccf-.2)<1e-12,q$workout_losses[[1]]$economic_lgd==0,abs(q$workout_losses[[2]]$economic_lgd-.65)<1e-12,q$cure_targets[[1]]$cure_at=='2024-05-20',q$cure_targets[[1]]$redefault_at=='2024-06-20',q$episodes$episodes[[2]]$previous_episode_id==q$episodes$episodes[[1]]$episode_id)
stopifnot(abs(q$validation_metrics$vintage$cells[[4]]$cumulative$mean_outcome-1/3)<1e-12,abs(q$validation_metrics$collections$overall$discounted_net$bias-((.6*600+.6*200-(600+80-10))/2))<1e-9,q$validation_metrics$retail_pool$pools[[1]]$pd_count_weighted$observed_rate==.5,q$validation_metrics$retail_pool$pools[[1]]$pd_exposure_weighted$observed_rate==1,q$phase_details$delinquency$dpd==14,!q$phase_details$arrangement$contract_changed,!q$phase_details$action_history$rows[[1]]$accepted)
stopifnot(all(vapply(Filter(function(s)s$account_id=='card-main'&&s$as_of>='2024-04-30',q$panel),function(s)!s$at_risk,TRUE)),all(vapply(Filter(function(s)s$account_id=='card-zero',q$panel),function(s)s$at_risk,TRUE)),all(vapply(raw$governance$rows,function(g)g$replay$status=='REPRODUCED',TRUE)),all(unlist(raw$replay$known_limits)==c(1000,600)),identical(content_fingerprint(do.call(replay_consistency,raw$replay$input)$value)$value,content_fingerprint(raw$replay$validation)$value))
wrong<-raw$origin$model;wrong$application_contract$product_ids<-list('OTHER_PRODUCT')
stopifnot(inherits(try(predict_application_risk(raw$origin$snapshots[[2]],wrong,wrong$target,calibrator=raw$origin$calibrator),silent=TRUE),'try-error'))
diag<-raw$linked_diagnostics;chain<-diag$collections
stopifnot(chain$cure_targets[[1]]$cure_at=='2024-05-20',chain$cure_targets[[1]]$redefault_at=='2024-06-20',chain$remaining_claim==600,chain$prior_discounted_recovery==0,abs(chain$action_value$expected_net_recovery-(.25*(7/12*600-5)+.75*120-2))<1e-10,all(vapply(chain$missing_probation_targets,function(t)is.null(t$cure_label),TRUE)),abs(diag$lifetime_loss$lifetime_expected_loss-.4*1000*(1-.9^8))<1e-8,abs(diag$path_loss$expected_loss-diag$lifetime_loss$lifetime_expected_loss)<1e-8,diag$default_count$overall$observed_count==5,diag$default_count$overall$observed_defaults==1,identical(content_fingerprint(do.call(validation_report,diag$report_inputs)$value)$value,content_fingerprint(diag$validation_report)$value))
x<-d$cases[[card]];x$statements[[1]]$balance<-x$statements[[1]]$balance+1;stopifnot(inherits(try(.rl_verify_ledgers(x),silent=TRUE),'try-error'))
x<-d$cases[[card]];x$execution_inputs$vintage$account_outcomes[[1]]$cumulative_default<-1;stopifnot(inherits(try(.rl_verify_ledgers(x),silent=TRUE),'try-error'))
x<-d$cases[[card]];x$new_draw_contract$known_at<-'2024-06-02';stopifnot(inherits(try(.rl_verify_ledgers(x),silent=TRUE),'try-error'))
if(Sys.getenv('CREDITRATINGSYSTEM_EXTENDED_TESTS')=='true'){
 all<-do.call(run_revolving_lifecycle,args)
 expected<-list(RETAIL_CREDIT_CARD=c(.03,750,.65),RETAIL_CHARGE_CARD=c(.02,sqrt(400*600)*exp((log(600/400)/2)^2/2),.525),RETAIL_OVERDRAFT=c(.04,850,.75),RETAIL_HOME_EQUITY_LINE=c(.015,62500,.55))
 for(p in names(expected)){q<-all$products[[p]];e<-expected[[p]];stopifnot(all(unlist(q$application_pd)==e[1]),abs(unlist(q$ead_forecast)-e[2])<1e-8,abs(q$workout_losses[[2]]$economic_lgd-e[3])<1e-12,q$cohort_contract_status=='PASS',q$replay_status=='PASS')}
 h<-all$products$RETAIL_HOME_EQUITY_LINE$phase_details$household;a<-all$raw_artifacts$products$RETAIL_HOME_EQUITY_LINE
 stopifnot(h$joint$monthly_income==5000,h$joint$monthly_debt_service==1000,abs(h$stress_projection$periods[[1]]$residual+1500)<1e-9,a$validation$affordability$decision$status=='PASS',identical(content_fingerprint(do.call(affordability_stress_backtest,a$affordability_inputs)$value)$value,content_fingerprint(a$validation$affordability)$value))
}

a<-do.call(run_revolving_lifecycle,c(args,list(product_ids='RETAIL_HOME_EQUITY_LINE')))$raw_artifacts$products$RETAIL_HOME_EQUITY_LINE
stopifnot(abs(a$validation$lgd$metrics$overall$count_weighted$bias-.125)<1e-10,abs(a$validation$lgd$metrics$overall$ead_weighted$bias-.2625)<1e-10,all(vapply(a$workout$lgd_validation_input$records,function(r)r$cluster_id,'')=='heloc-main-person-household'),identical(do.call(lgd_backtest,a$workout$lgd_validation_input)$value,a$validation$lgd))
